    # 2 - (200) GET:/api/get_collector
    # 3 - (401) GET:/api/get_collector
    # Found 1 potential fault of type-code 201
    @timeout_decorator.timeout(60)
    def test_37_get_on_get_collector_vulnerableToXSS(self):
        
        headers = {}
        headers["content-type"] = "application/x-www-form-urlencoded"
        body = "username=pyload&password=pyload"
        cookies_pyload_jar = requests \
                .post(self.baseUrlOfSut + "/login", 
                    headers=headers, data=body, allow_redirects=False, verify=False).cookies
        cookies_pyload = requests.utils.dict_from_cookiejar(cookies_pyload_jar)
        
        headers = {}
        headers["content-type"] = "application/x-www-form-urlencoded"
        body = "username=alice&password=alicepass"
        cookies_alice_jar = requests \
                .post(self.baseUrlOfSut + "/login", 
                    headers=headers, data=body, allow_redirects=False, verify=False).cookies
        cookies_alice = requests.utils.dict_from_cookiejar(cookies_alice_jar)
        
        
        headers = {}
        headers['Accept'] = "application/json"
        res_0 = requests \
                .get(self.baseUrlOfSut + "/api/get_collector",
                    headers=headers, cookies=cookies_pyload, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_0.status_code == 401
        assert "www-authenticate" not in res_0.headers
        assert "application/json" in res_0.headers["content-type"]
        assert res_0.json()["error"] == "Access denied"
        
        # Fault201. Cross-Site Scripting (XSS).
        headers = {}
        headers['Accept'] = "application/json"
        res_1 = requests \
                .get(self.baseUrlOfSut + "/api/get_collector",
                    headers=headers, cookies=cookies_alice, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_1.status_code == 200
        assert "application/json" in res_1.headers["content-type"]
        assert len(res_1.json()) == 776
        assert res_1.json()[0]["pid"] == 551
        assert res_1.json()[0]["name"] == "New Package"
        assert res_1.json()[0]["folder"] == "New Package"
        assert res_1.json()[0]["site"] == ""
        assert res_1.json()[0]["password"] == ""
        assert res_1.json()[0]["dest"] == 0
        assert res_1.json()[0]["order"] == -1205205490
        assert res_1.json()[0]["linksdone"] == 0
        assert res_1.json()[0]["sizedone"] == 0
